script:
frappe.ui.form.on("Sales Order", {
    company(frm) {
        // Clear existing warehouse if company changes
        frm.set_value("set_warehouse", null);

        set_warehouse_filter(frm);
    },

    setup(frm) {
        set_warehouse_filter(frm);
    }
});

function set_warehouse_filter(frm) {
    frm.set_query("set_warehouse", function() {
        return {
            filters: {
                company: frm.doc.company
            }
        };
    });
}

frappe.ui.form.on('Quotation', {
    setup: function(frm) {

        frm.set_query('custom_transporter_', function() {
            return {
                filters: {
                    'is_transporter': 1
                }
            };
        });

    }
});
